-- A57: batch b001_es, chunk 2 (25 videos for learners of es). Guarded: nothing is written when a row of
-- this chunk exists already (the whole transaction stops); English (media_exercise_sets) is not touched.
begin;
do $g$ begin
  if exists (select 1 from public.media_exercise_sets_l10n where learning_language = 'es' and media_id in (811,7053,704,247,775,4710,4760,5007,659,5609,4055,665,518,332,82,38,785,4058,7999,7180,449,4568,721,7059,5673)) then
    raise exception 'A57 out/b001_es_02.sql: rows exist already - nothing written';
  end if;
end $g$;
do $g$ begin
  if (select count(*) from public.media_exercise_sets_l10n where learning_language = 'es' and media_id in (811,7053,704,247,775,4710,4760,5007,659,5609,4055,665,518,332,82,38,785,4058,7999,7180,449,4568,721,7059,5673)) <> 25 then
    raise exception 'A57 out/b001_es_02.sql: not 25 rows after the insert';
  end if;
end $g$;
commit;
